def read_csv(text):
    lines = text.strip().split('\n')
    header = lines[0].split(',')
    result = []
    for line in lines[1:]:
        fields = []
        field = []
        in_quotes = False
        for part in line.split('\n'):
            for char in part:
                if char == '"':
                    in_quotes = not in_quotes
                elif char == ',' and not in_quotes:
                    fields.append(''.join(field))
                    field = []
                else:
                    field.append(char)
            if part.endswith('"'):
                in_quotes = False
        if field:
            fields.append(''.join(field))
        result.append(dict(zip(header, fields)))
    return result

