from io import StringIO

def write_csv(rows, fieldnames):
    # StringIO 객체 생성
    output = StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')

    # 헤더 작성
    writer.writeheader()

    # 각 행 작성
    for row in rows:
        writer.writerow(row)

    # StringIO 객체의 내용을 문자열로 반환
    return output.getvalue()

# 기존 함수 유지 (만약 다른 용도로 사용되는 경우)
