def read_csv(text):
    import csv
    from io import StringIO

    # CSV 문자열을 StringIO 객체로 변환하여 csv 모듈 사용
    csv_reader = csv.DictReader(StringIO(text), delimiter=',', quotechar='"', skipinitialspace=True)

    # 헤더와 데이터를 리스트로 변환
    header = csv_reader.fieldnames
    rows = [{k: v.strip() if v else '' for k, v in row.items()} for row in csv_reader]

    # 내부 따옴표 처리 및 빈 필드 유지
    processed_rows = []
    for row in rows:
        processed_row = {k: v.replace('""', '"') if '"' in v else v for k, v in row.items()}
        processed_rows.append(processed_row)

    return processed_rows

def write_csv(rows, fieldnames):
    return ','.join(fieldnames) + '\n' + ''.join(','.join(row.get(k, '') for k in fieldnames) + '\n' for row in rows)

